// Class 12 English Core - Flamingo Poetry Chapter 10: Keeping Quiet
// Fully standardized to English Core Blueprint & AGENTS.md guidelines

export const c12EngF10HtmlOverview = "\n<div style=\"padding: 18px; color: #F8FAFC; text-align: justify; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.85; font-size: 15px;\">\n  <!-- Chapter Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(0, 229, 255, 0.18), rgba(15, 23, 42, 0.95)); border: 1.5px solid #00E5FF; border-radius: 14px; padding: 22px; margin-bottom: 24px; box-shadow: 0 8px 24px rgba(0,0,0,0.35);\">\n    <div style=\"display: flex; align-items: center; gap: 12px; margin-bottom: 10px;\">\n      <span style=\"background: #00E5FF; color: #0F172A; font-weight: 800; font-size: 12px; padding: 4px 10px; border-radius: 6px; text-transform: uppercase; letter-spacing: 1px;\">Poem 10 • Flamingo Poetry</span>\n      <span style=\"color: #94A3B8; font-size: 13px; font-weight: 600;\">Core Literature • Class 12 English</span>\n    </div>\n    <h1 style=\"color: #FFFFFF; font-size: 26px; font-weight: 800; margin: 0 0 8px 0; letter-spacing: -0.5px;\">Keeping Quiet</h1>\n    <p style=\"color: #00E5FF; font-size: 15px; font-weight: 600; margin: 0 0 12px 0;\">By Pablo Neruda (1904–1973) • Nobel Prize in Literature (1971)</p>\n    <p style=\"color: #CBD5E1; font-size: 14px; line-height: 1.6; margin: 0;\">A meditative, humanitarian appeal for universal silence, quiet introspection, cessation of mechanised frenzy and lethal warfare, and a profound rebirth inspired by the dormant regeneration of the living Earth.</p>\n  </div>\n\n  <!-- Poet Background & Context -->\n  <div style=\"background: rgba(30, 41, 59, 0.7); border-left: 4px solid #00E5FF; border-radius: 0 12px 12px 0; padding: 18px 20px; margin-bottom: 24px;\">\n    <h3 style=\"color: #00E5FF; margin: 0 0 10px 0; font-size: 18px; font-weight: 700;\">1. About the Poet & Philosophical Backdrop</h3>\n    <p style=\"margin: 0 0 10px 0;\">Pablo Neruda (pen name of <b style=\"color: #00E5FF;\">Neftalí Ricardo Reyes Basoalto</b>) was a visionary Chilean diplomat, politician, and poet who won the Nobel Prize in Literature in 1971. Renowned for writing passionate love sonnets, surrealist manifestos, and epic historical tapestries (<i style=\"color: #00E5FF;\">Canto General</i>), Neruda was deeply affected by the devastating civil wars, nuclear arms escalation, and ecological plunder of the twentieth century.</p>\n    <p style=\"margin: 0;\"><b style=\"color: #00E5FF;\">Context & Spirit of the Poem:</b> In <i style=\"color: #00E5FF;\">Keeping Quiet</i> (originally written in Spanish), Neruda does not advocate cowardly retreat or ascetic withdrawal from the universe. Rather, he proposes an antidote to our modern existential sickness: an unhurried, collective pause where all humanity suspends aggressive speech, nationalistic confrontation, environmental destruction, and frantic motion to reclaim self-knowledge, ecological empathy, and universal fraternity.</p>\n  </div>\n\n  <!-- Stanza-by-Stanza Deep Analysis -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 12px; padding: 20px; margin-bottom: 24px;\">\n    <h3 style=\"color: #00E5FF; margin: 0 0 16px 0; font-size: 18px; font-weight: 700;\">2. Stanza-by-Stanza Critical Analysis</h3>\n    \n    <div style=\"margin-bottom: 16px; padding-bottom: 14px; border-bottom: 1px dashed rgba(255,255,255,0.1);\">\n      <h4 style=\"color: #F1F5F9; font-size: 15px; margin: 0 0 8px 0;\"><b style=\"color: #00E5FF;\">Stanza 1: The Call for Collective Immobility (Counting to Twelve)</b></h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 14px;\">The poet opens with a tranquil injunction: <i style=\"color: #FFFFFF;\">\"Now we will count to twelve / and we will all keep still.\"</i> The number twelve serves as a cosmic symbol encompassing human measurement of time—the twelve divisions of the clock face and the twelve months of the solar year. Neruda urges human beings across the globe to suspend verbal interaction (<i style=\"color: #FFFFFF;\">\"not speak in any language\"</i>) and mechanical exertion (<i style=\"color: #FFFFFF;\">\"not move our arms so much\"</i>). Language, which has frequently mutated into a weapon of chauvinistic divide and political discord, is silenced to allow universal soul-speech to flourish.</p>\n    </div>\n\n    <div style=\"margin-bottom: 16px; padding-bottom: 14px; border-bottom: 1px dashed rgba(255,255,255,0.1);\">\n      <h4 style=\"color: #F1F5F9; font-size: 15px; margin: 0 0 8px 0;\"><b style=\"color: #00E5FF;\">Stanza 2: The Exotic Moment of Universal Stillness</b></h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 14px;\">Neruda envisions the consequence of this universal silence as an <i style=\"color: #FFFFFF;\">\"exotic moment\"</i>—rare, extraordinary, and pristine—free from the deafening clamour of engines, factory dynamos, and frantic commercial deadlines. In this shared hiatus, all artificial socioeconomic hierarchies and geopolitical demarcations dissolve, binding humankind in a mesmerizing, serene unity: <i style=\"color: #FFFFFF;\">\"we would all be together / in a sudden strangeness.\"</i></p>\n    </div>\n\n    <div style=\"margin-bottom: 16px; padding-bottom: 14px; border-bottom: 1px dashed rgba(255,255,255,0.1);\">\n      <h4 style=\"color: #F1F5F9; font-size: 15px; margin: 0 0 8px 0;\"><b style=\"color: #00E5FF;\">Stanza 3: Cessation of Ecological & Self-Inflicted Violence</b></h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 14px;\">Stillness instantly curtails destructive human exploitation of nature and of the self. Fishermen trawling polar seas would cease harpooning the endangered whales, reflecting environmental rehabilitation. Simultaneously, the salt gatherer, driven by grinding economic survival, would pause to examine his own <i style=\"color: #FFFFFF;\">\"hurt hands\"</i>, recognizing that relentless material pursuit has fractured his physical and spiritual wholeness.</p>\n    </div>\n\n    <div style=\"margin-bottom: 16px; padding-bottom: 14px; border-bottom: 1px dashed rgba(255,255,255,0.1);\">\n      <h4 style=\"color: #F1F5F9; font-size: 15px; margin: 0 0 8px 0;\"><b style=\"color: #00E5FF;\">Stanza 4: Renunciation of Warfare & Brotherhood in the Shade</b></h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 14px;\">The poet unleashes a stinging moral critique against warmongers orchestrating <i style=\"color: #FFFFFF;\">\"green wars\"</i> (deforestation, agricultural devastation), chemical attacks (<i style=\"color: #FFFFFF;\">\"wars with gas\"</i>), and high-tech warfare (<i style=\"color: #FFFFFF;\">\"wars with fire\"</i>). He exposes the grotesque irony of modern combat: achieving <i style=\"color: #FFFFFF;\">\"victory with no survivors\"</i>. The perpetrators are exhorted to put on immaculate clean clothes (shedding war-stained ideologies) and walk companionably with former adversaries under the protective shade of peace, doing nothing destructive.</p>\n    </div>\n\n    <div style=\"margin-bottom: 16px; padding-bottom: 14px; border-bottom: 1px dashed rgba(255,255,255,0.1);\">\n      <h4 style=\"color: #F1F5F9; font-size: 15px; margin: 0 0 8px 0;\"><b style=\"color: #00E5FF;\">Stanza 5: Total Inactivity vs. Living Dynamism</b></h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 14px;\">To forestall philosophical nihilism, Neruda firmly clarifies: <i style=\"color: #FFFFFF;\">\"What I want should not be confused / with total inactivity. / Life is what it is about; / I want no truck with death.\"</i> Quietness is not morbid rigor mortis or sterile defeatism. The tragedy of modern mankind is relentless, single-minded tunnel vision focused solely on selfish economic survival (<i style=\"color: #FFFFFF;\">\"single-minded / about keeping our lives moving\"</i>), blind to the existential sadness born of spiritual emptiness and perpetual fear of death.</p>\n    </div>\n\n    <div>\n      <h4 style=\"color: #F1F5F9; font-size: 15px; margin: 0 0 8px 0;\"><b style=\"color: #00E5FF;\">Stanza 6: Earth as the Supreme Teacher & The Poet's Departure</b></h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 14px;\">Nature provides the ultimate vindication of Neruda's thesis. During winter or periods of drought, the Earth appears dormant, barren, and dead, yet beneath the still soil, seeds silently germinate to erupt into vibrant spring life. True silence nurtures internal creative rebirth. Having delivered his universal message, the poet gracefully passes the mantle of meditative renewal to the reader: <i style=\"color: #FFFFFF;\">\"Now I'll count up to twelve / and you keep quiet and I will go.\"</i></p>\n    </div>\n  </div>\n\n  <!-- Master Poetic Devices Table -->\n  <div style=\"background: rgba(30, 41, 59, 0.85); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 12px; padding: 20px; margin-bottom: 24px;\">\n    <h3 style=\"color: #00E5FF; margin: 0 0 16px 0; font-size: 18px; font-weight: 700;\">3. Master Literary & Poetic Devices Table</h3>\n    <div style=\"overflow-x: auto;\">\n      <table style=\"width: 100%; border-collapse: collapse; font-size: 14px; text-align: left;\">\n        <thead>\n          <tr style=\"background: rgba(0, 229, 255, 0.15); border-bottom: 2px solid #00E5FF;\">\n            <th style=\"padding: 10px 12px; color: #00E5FF;\">Poetic Device</th>\n            <th style=\"padding: 10px 12px; color: #FFFFFF;\">Example from Poem</th>\n            <th style=\"padding: 10px 12px; color: #CBD5E1;\">Poetic Significance & Explanation</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.06);\">\n            <td style=\"padding: 10px 12px; font-weight: bold; color: #00E5FF;\">Symbolism</td>\n            <td style=\"padding: 10px 12px; color: #F1F5F9;\">\"count to twelve\"<br/>\"hurt hands\"<br/>\"clean clothes\"</td>\n            <td style=\"padding: 10px 12px; color: #CBD5E1;\">Twelve represents cosmic completion (clock hours, solar months); hurt hands represent self-inflicted wounds of commerce; clean clothes signify renewed moral purity and fraternity.</td>\n          </tr>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.06); background: rgba(15, 23, 42, 0.4);\">\n            <td style=\"padding: 10px 12px; font-weight: bold; color: #00E5FF;\">Pun (Double Meaning)</td>\n            <td style=\"padding: 10px 12px; color: #F1F5F9;\">\"not move our arms so much\"</td>\n            <td style=\"padding: 10px 12px; color: #CBD5E1;\">'Arms' signifies both anatomical human limbs and destructive ballistic weaponry, pleading simultaneously for physical pause and global disarmament.</td>\n          </tr>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.06);\">\n            <td style=\"padding: 10px 12px; font-weight: bold; color: #00E5FF;\">Paradox / Antithesis</td>\n            <td style=\"padding: 10px 12px; color: #F1F5F9;\">\"victory with no survivors\"</td>\n            <td style=\"padding: 10px 12px; color: #CBD5E1;\">Exposes the self-annihilating folly of modern warfare where ideological victory is pyrrhic because all human life is exterminated.</td>\n          </tr>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.06); background: rgba(15, 23, 42, 0.4);\">\n            <td style=\"padding: 10px 12px; font-weight: bold; color: #00E5FF;\">Personification</td>\n            <td style=\"padding: 10px 12px; color: #F1F5F9;\">\"Perhaps the Earth can teach us\"</td>\n            <td style=\"padding: 10px 12px; color: #CBD5E1;\">Earth is personified as a patient, wise guru demonstrating that dormancy is an essential prelude to vibrant regeneration.</td>\n          </tr>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.06);\">\n            <td style=\"padding: 10px 12px; font-weight: bold; color: #00E5FF;\">Metaphor</td>\n            <td style=\"padding: 10px 12px; color: #F1F5F9;\">\"shade\"<br/>\"put on clean clothes\"</td>\n            <td style=\"padding: 10px 12px; color: #CBD5E1;\">'Shade' metaphors peaceful, non-combative coexistence; 'clean clothes' metaphors casting aside bloodstained military doctrines.</td>\n          </tr>\n          <tr>\n            <td style=\"padding: 10px 12px; font-weight: bold; color: #00E5FF;\">Alliteration</td>\n            <td style=\"padding: 10px 12px; color: #F1F5F9;\">\"sudden strangeness\"<br/>\"hurt hands\"<br/>\"clean clothes\"<br/>\"wars with\"</td>\n            <td style=\"padding: 10px 12px; color: #CBD5E1;\">Consonant sound repetitions create rhythmic melody, reinforcing the meditative, echoing atmosphere of stillness.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n\n  <!-- Vocabulary Glossary -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 4px solid #00E5FF; border-radius: 0 12px 12px 0; padding: 18px 20px;\">\n    <h3 style=\"color: #00E5FF; margin: 0 0 12px 0; font-size: 17px; font-weight: 700;\">4. Essential Stanza Vocabulary</h3>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; font-size: 13px;\">\n      <div><b style=\"color: #00E5FF;\">Exotic:</b> Extraordinary, strikingly unusual, serene.</div>\n      <div><b style=\"color: #00E5FF;\">Green wars:</b> Man-made ecological destruction of biosphere.</div>\n      <div><b style=\"color: #00E5FF;\">Truck with:</b> (Idiom) Association, pact, or compromise.</div>\n      <div><b style=\"color: #00E5FF;\">Single-minded:</b> Tunnel-visioned pursuit of material survival.</div>\n      <div><b style=\"color: #00E5FF;\">Sudden strangeness:</b> Rare feeling of universal, unified calm.</div>\n      <div><b style=\"color: #00E5FF;\">Interrupt:</b> Punctuate and dissolve habitual existential grief.</div>\n    </div>\n  </div>\n</div>\n";

export const c12EngF10HtmlSolutions = "\n<div style=\"padding: 16px; color: #F8FAFC; text-align: justify; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.85; font-size: 15px;\">\n\n  <!-- SECTION A: EXTRACT-BASED QUESTIONS -->\n  <div style=\"margin-bottom: 30px;\">\n    <div style=\"background: linear-gradient(135deg, rgba(0, 229, 255, 0.25), rgba(15, 23, 42, 0.95)); border: 1.5px solid #00E5FF; border-radius: 12px; padding: 14px 18px; margin-bottom: 20px;\">\n      <h2 style=\"color: #FFFFFF; font-size: 20px; font-weight: 800; margin: 0 0 4px 0;\">SECTION A: Extract-Based Questions (16 Marks)</h2>\n      <p style=\"color: #00E5FF; font-size: 13px; font-weight: 600; margin: 0;\">Board Pattern: 4 Objective Extracts • 4 Questions Each • Continuous Q1 to Q16</p>\n    </div>\n\n    <!-- Extract 1 -->\n    <div style=\"background: rgba(30, 41, 59, 0.7); border-left: 4px solid #00E5FF; border-radius: 0 10px 10px 0; padding: 14px 18px; margin-bottom: 16px;\">\n      <p style=\"font-style: italic; color: #E2E8F0; margin: 0 0 8px 0; font-size: 14px;\">\n        \"Now we will count to twelve<br/>\n        and we will all keep still.<br/>\n        For once on the face of the Earth<br/>\n        let's not speak in any language,<br/>\n        let's stop for one second,<br/>\n        and not move our arms so much.\"\n      </p>\n      <span style=\"color: #00E5FF; font-size: 12px; font-weight: 700;\">— Extract 1 (Stanza 1)</span>\n    </div>\n\n    <!-- Q1 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q1: What does the poet signify by asking humanity to \"count to twelve\"?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> The number twelve signifies the universal measurement of time—the twelve markings on a clock face and the twelve months of the year. Counting to twelve provides a brief, focused interval for humanity to suspend mechanical momentum and enter a unified state of silent meditation.</p>\n    </div>\n\n    <!-- Q2 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q2: Why does the poet specifically urge us \"not to speak in any language\"?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> Spoken language has historically served as a prime catalyst for nationalistic divisions, sectarian chauvinism, verbal hostility, and misunderstandings. By asking everyone to refrain from spoken tongue, Neruda creates a universal silence where all linguistic prejudices dissolve into soul-level communion.</p>\n    </div>\n\n    <!-- Q3 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q3: Identify and explain the poetic device in the line \"not move our arms so much\".</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> The device is a <b style=\"color: #00E5FF;\">Pun</b> (double meaning). 'Arms' refers literally to physical human limbs used for relentless, frantic labor, and metaphorically to weapons, munitions, and armaments used in violent warfare. Neruda calls simultaneously for physical calm and global disarmament.</p>\n    </div>\n\n    <!-- Q4 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 22px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q4: What is the tone of the speaker in the opening stanza?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> The tone is calm, persuasive, meditative, and gently authoritative. Rather than issuing a tyrannical mandate, the speaker invites all humanity collectively through inclusive pronouns (\"we will count\", \"let's stop\").</p>\n    </div>\n\n    <!-- Extract 2 -->\n    <div style=\"background: rgba(30, 41, 59, 0.7); border-left: 4px solid #00E5FF; border-radius: 0 10px 10px 0; padding: 14px 18px; margin-bottom: 16px;\">\n      <p style=\"font-style: italic; color: #E2E8F0; margin: 0 0 8px 0; font-size: 14px;\">\n        \"It would be an exotic moment<br/>\n        without rush, without engines,<br/>\n        we would all be together<br/>\n        in a sudden strangeness.<br/>\n        Fishermen in the cold sea<br/>\n        would not harm whales<br/>\n        and the man gathering salt<br/>\n        would look at his hurt hands.\"\n      </p>\n      <span style=\"color: #00E5FF; font-size: 12px; font-weight: 700;\">— Extract 2 (Stanzas 2 & 3)</span>\n    </div>\n\n    <!-- Q5 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q5: Why does the poet characterize this collective stillness as an \"exotic moment\"?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> It is 'exotic' because modern civilization has become entirely subordinated to relentless haste, factory sirens, automotive noise, and industrial commotion. A complete worldwide cessation of noise and mechanical acceleration is an extraordinary, hitherto unexperienced phenomenon.</p>\n    </div>\n\n    <!-- Q6 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q6: How does the silence impact the relationship between man and wildlife?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> In the silence, fishermen in polar waters cease their ruthless predation upon majestic whales. The hiatus interrupts anthropogenic ecological destruction and safeguards marine life from industrial slaughter.</p>\n    </div>\n\n    <!-- Q7 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q7: What does the salt gatherer realize when he looks at his \"hurt hands\"?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> Driven by ruthless economic necessity, the salt gatherer never paused to acknowledge his own bodily trauma. The quiet interval compels him to look at his corrosive, ulcerated hands, awakening him to how relentless commercial exploitation damages human well-being.</p>\n    </div>\n\n    <!-- Q8 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 22px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q8: Identify the poetic device in \"sudden strangeness\" and \"hurt hands\".</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> Both phrases employ <b style=\"color: #00E5FF;\">Alliteration</b>—the repetition of consonant sounds ('s' in <i>sudden strangeness</i> and 'h' in <i>hurt hands</i>), generating phonetic resonance that underscores the stillness and visceral pain.</p>\n    </div>\n\n    <!-- Extract 3 -->\n    <div style=\"background: rgba(30, 41, 59, 0.7); border-left: 4px solid #00E5FF; border-radius: 0 10px 10px 0; padding: 14px 18px; margin-bottom: 16px;\">\n      <p style=\"font-style: italic; color: #E2E8F0; margin: 0 0 8px 0; font-size: 14px;\">\n        \"Those who prepare green wars,<br/>\n        wars with gas, wars with fire,<br/>\n        victory with no survivors,<br/>\n        would put on clean clothes<br/>\n        and walk about with their brothers<br/>\n        in the shade, doing nothing.\"\n      </p>\n      <span style=\"color: #00E5FF; font-size: 12px; font-weight: 700;\">— Extract 3 (Stanza 4)</span>\n    </div>\n\n    <!-- Q9 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q9: What types of warfare are highlighted by the poet in this stanza?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> Neruda catalogs three catastrophic forms of conflict: <b style=\"color: #00E5FF;\">green wars</b> (environmental decimation, deforestation, and biological warfare), <b style=\"color: #00E5FF;\">wars with gas</b> (chemical and toxic warfare), and <b style=\"color: #00E5FF;\">wars with fire</b> (incendiary, nuclear, and conventional thermal bombardments).</p>\n    </div>\n\n    <!-- Q10 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q10: Explain the biting paradox contained in \"victory with no survivors\".</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> It is a sharp <b style=\"color: #00E5FF;\">Paradox</b> exposing the absurdity of modern mechanized combat. If a war results in the total extermination of combatants and civilians alike, the proclaimed 'victory' is hollow and meaningless, leaving behind only an apocalyptic cemetery with no one alive to celebrate.</p>\n    </div>\n\n    <!-- Q11 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q11: What is the symbolic significance of \"putting on clean clothes\"?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> Putting on clean clothes symbolizes shedding bloodstained military uniforms, shedding violent ideological doctrines, and initiating a renewed, pure moral consciousness dedicated to non-violence and fraternity.</p>\n    </div>\n\n    <!-- Q12 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 22px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q12: What does \"in the shade, doing nothing\" suggest?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> 'In the shade' metaphorically symbolizes a protective haven of peace, cool comfort, and egalitarian brotherhood. 'Doing nothing' denotes an active suspension of malicious, warlike schemes in favor of tranquil coexistence.</p>\n    </div>\n\n    <!-- Extract 4 -->\n    <div style=\"background: rgba(30, 41, 59, 0.7); border-left: 4px solid #00E5FF; border-radius: 0 10px 10px 0; padding: 14px 18px; margin-bottom: 16px;\">\n      <p style=\"font-style: italic; color: #E2E8F0; margin: 0 0 8px 0; font-size: 14px;\">\n        \"Perhaps the Earth can teach us<br/>\n        as when everything seems dead<br/>\n        and later proves to be alive.<br/>\n        Now I'll count up to twelve<br/>\n        and you keep quiet and I will go.\"\n      </p>\n      <span style=\"color: #00E5FF; font-size: 12px; font-weight: 700;\">— Extract 4 (Stanza 6)</span>\n    </div>\n\n    <!-- Q13 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q13: What vital lesson does the Earth teach humanity?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> The Earth demonstrates that stillness is not terminal death. In winter or severe drought, nature appears completely lifeless, yet subterranean processes are silently preparing seeds to erupt into radiant blossoms when spring arrives. Similarly, quiet introspection rejuvenates human spirit.</p>\n    </div>\n\n    <!-- Q14 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q14: Identify the literary device used in \"Perhaps the Earth can teach us\".</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> <b style=\"color: #00E5FF;\">Personification</b>. The Earth is attributed with the human qualities of a wise, patient mentor and teacher guiding human pupils away from destructive haste.</p>\n    </div>\n\n    <!-- Q15 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q15: Why does the poet say \"and I will go\" at the very end?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> Having imparted his philosophical vision, the poet withdraws unobtrusively. He leaves the reader in solitary, personal introspection to practice the silence independently without need for outside prompting.</p>\n    </div>\n\n    <!-- Q16 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 22px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q16: How does this stanza resolve the central conflict of the poem?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> It harmonizes stillness with dynamic life, reassuring humanity that silence is not inactive death but rather the ultimate source of regeneration, moral clarity, and enduring vitality.</p>\n    </div>\n  </div>\n\n  <!-- SECTION B: SHORT ANSWER QUESTIONS -->\n  <div style=\"margin-bottom: 30px;\">\n    <div style=\"background: linear-gradient(135deg, rgba(0, 229, 255, 0.25), rgba(15, 23, 42, 0.95)); border: 1.5px solid #00E5FF; border-radius: 12px; padding: 14px 18px; margin-bottom: 20px;\">\n      <h2 style=\"color: #FFFFFF; font-size: 20px; font-weight: 800; margin: 0 0 4px 0;\">SECTION B: Short Answer Questions (3 Marks • 40–50 Words)</h2>\n      <p style=\"color: #00E5FF; font-size: 13px; font-weight: 600; margin: 0;\">Board Standard: Analytical Reasoning • Exactly 12 Questions (Q17 to Q28)</p>\n    </div>\n\n    <!-- Q17 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E5FF; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q17: Why does Pablo Neruda advocate temporary silence rather than permanent withdrawal?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> Neruda expressly clarifies that his stillness is not escapism or morbid inaction. A brief pause allows humanity to halt toxic momentum, examine inner motives, and return to active life with elevated empathy, moral sanity, and renewed vigor.</p>\n    </div>\n\n    <!-- Q18 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E5FF; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q18: What is the \"sadness\" that Neruda mentions in the poem?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> The \"sadness\" stems from modern man's failure to understand his own authentic spiritual self, coupled with perpetual fear of mortality. Humans race frantically after material trophies, never experiencing communion, thereby intensifying existential gloom.</p>\n    </div>\n\n    <!-- Q19 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E5FF; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q19: How can a huge silence interrupt the sadness of modern life?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> A collective deep silence breaks the monotonous, self-destructive cycle of commercial panic and warmongering. It creates an introspective space where humans can heal their spiritual fractures and realize their fundamental oneness with creation.</p>\n    </div>\n\n    <!-- Q20 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E5FF; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q20: What does the poet mean by saying \"I want no truck with death\"?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> Using the idiomatic expression \"have no truck with\" (refuse association with), Neruda emphatically rejects any equivalence between his quietude and bodily death. His philosophy is an affirmation of vivid, purposeful living, not cold physical extinction.</p>\n    </div>\n\n    <!-- Q21 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E5FF; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q21: How are fishermen and salt gatherers symbolic of human activity?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> The fishermen embody mankind's ruthless overexploitation of nature and destruction of biodiversity. The salt gatherer represents relentless, self-injurious labor where economic survival blindingly causes humans to disregard their own agony.</p>\n    </div>\n\n    <!-- Q22 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E5FF; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q22: Why does Neruda refer to all nations speaking \"no language\"?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> Language barriers have frequently fostered cultural jingoism, mutual suspicion, and political discord. Suspending speech removes superficial barriers, allowing people of divergent nationalities to connect through universal silence.</p>\n    </div>\n\n    <!-- Q23 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E5FF; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q23: How does the concept of \"brotherhood\" emerge during the quiet interval?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> When warmongers and ideological rivals pause their destructive agendas, put on clean garments, and walk peacefully side by side in the shade, enmity is extinguished, revealing that all human beings share a common fraternal destiny.</p>\n    </div>\n\n    <!-- Q24 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E5FF; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q24: What is the significance of the seasonal cycle of Earth in the poem?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> The seasonal transition from barren winter to flourishing spring proves that apparent stillness is actually vibrant incubation. Nature uses dormant phases to nurture future growth, illustrating the restorative potential of human silence.</p>\n    </div>\n\n    <!-- Q25 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E5FF; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q25: Why is modern man described as being \"single-minded\"?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> Man is narrow-mindedly obsessed with material progress, economic survival, and keeping his physical routine moving at breakneck speed. This obsessive tunnel vision blinds him to spiritual depth and inner peace.</p>\n    </div>\n\n    <!-- Q26 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E5FF; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q26: What effect does the poem suggest silence will have on the environment?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> Silence halts ecological predation: polar seas will not see harpooning of whales, toxic industrial gases and chemical emissions will pause, and the earth will enjoy an essential respite to heal from anthropogenic exploitation.</p>\n    </div>\n\n    <!-- Q27 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E5FF; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q27: How does Neruda distinguish between silence and death?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> Death is absolute termination, cold inertness, and decay. Silence, conversely, is fertile dormancy—an intentional pause filled with reflective awareness that revitalizes the soul, just as quiet soil germinates a dormant seed.</p>\n    </div>\n\n    <!-- Q28 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border-left: 3px solid #00E5FF; border-radius: 0 10px 10px 0; padding: 14px 16px; margin-bottom: 22px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q28: Why does the poet end the poem with \"and I will go\"?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> Neruda's departure signifies that a mentor's duty ends once the vision is shared. The responsibility now rests with each reader to internalize the silence and undergo personal spiritual transformation without external interference.</p>\n    </div>\n  </div>\n\n  <!-- SECTION C: LONG ANSWER QUESTIONS -->\n  <div style=\"margin-bottom: 30px;\">\n    <div style=\"background: linear-gradient(135deg, rgba(0, 229, 255, 0.25), rgba(15, 23, 42, 0.95)); border: 1.5px solid #00E5FF; border-radius: 12px; padding: 14px 18px; margin-bottom: 20px;\">\n      <h2 style=\"color: #FFFFFF; font-size: 20px; font-weight: 800; margin: 0 0 4px 0;\">SECTION C: Long Analytical Questions (6 Marks • 120–150 Words)</h2>\n      <p style=\"color: #00E5FF; font-size: 13px; font-weight: 600; margin: 0;\">3-Tier Model: Context & Stanza Foundations • Thematic Architecture • Board Conclusion • Q29 to Q34</p>\n    </div>\n\n    <!-- Q29 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.3); border-radius: 12px; padding: 18px; margin-bottom: 18px;\">\n      <h3 style=\"color: #00E5FF; font-size: 16px; font-weight: 700; margin: 0 0 10px 0;\">Q29: Analyze Pablo Neruda's \"Keeping Quiet\" as a passionate anti-war manifesto and an urgent plea for environmental preservation.</h3>\n      <p style=\"margin: 0 0 8px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span></p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E5FF;\">1. Context & Anti-War Indictment:</b> In <i>Keeping Quiet</i>, Pablo Neruda mounts a fearless critique against contemporary warmongers who orchestrate \"green wars\" (ecocide and deforestation), \"wars with gas\" (chemical warfare), and \"wars with fire\" (nuclear and incendiary armaments). The poet exposes the lethal absurdity of modern conflicts through the devastating paradox: \"victory with no survivors\". A military triumph that leaves the biosphere devastated and the human race extinguished is grotesque self-annihilation.</p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E5FF;\">2. Ecological & Humanitarian Dimensions:</b> Neruda extends his anti-violence philosophy to non-human life. In the silence, fishermen cease harpooning whales in arctic oceans, halting anthropogenic predation. Simultaneously, the salt gatherer confronts his corrosive bodily trauma (\"hurt hands\"), recognizing how unchecked industrial greed brutalizes labor. The poet calls on aggressors to put on \"clean clothes\"—shedding blood-soaked uniforms and bellicose doctrines—and walk alongside their erstwhile enemies under the protective canopy of peace.</p>\n      <p style=\"margin: 0;\"><b style=\"color: #00E5FF;\">3. Critical Conclusion:</b> Thus, Neruda's poem transcends lyrical meditation to become an urgent, prophetic call for ecological stewardship, total disarmament, and universal brotherhood as the sole safeguards of human survival.</p>\n    </div>\n\n    <!-- Q30 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.3); border-radius: 12px; padding: 18px; margin-bottom: 18px;\">\n      <h3 style=\"color: #00E5FF; font-size: 16px; font-weight: 700; margin: 0 0 10px 0;\">Q30: How does the poet establish that quiet introspection is not equivalent to \"total inactivity\" or death?</h3>\n      <p style=\"margin: 0 0 8px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span></p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E5FF;\">1. Clarification & Rejection of Nihilism:</b> Recognizing that modern utilitarian society equates stillness with stagnation and lethargy, Neruda explicitly warns: <i>\"What I want should not be confused / with total inactivity.\"</i> He states unequivocally, <i>\"Life is what it is about; / I want no truck with death.\"</i> His stillness is neither ascetic renunciation nor nihilistic surrender, but a conscious, temporary disengagement from mechanized mania.</p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E5FF;\">2. Natural Analogy of Regeneration:</b> To validate his thesis, Neruda invokes the supreme tutelage of the Earth. In autumn and winter, nature appears utterly barren, frozen, and dead; yet subterranean root systems and dormant seeds are quietly synthesizing nutrients. When spring arrives, life erupts with unstoppable vitality. True stillness is therefore an active, creative gestation rather than terminal inertia.</p>\n      <p style=\"margin: 0;\"><b style=\"color: #00E5FF;\">3. Critical Conclusion:</b> Neruda brilliantly demonstrates that modern man's single-minded panic about \"keeping our lives moving\" breeds spiritual exhaustion. An introspective pause is not an encounter with death, but the vital breath that restores sanity, moral purpose, and enduring vitality to life.</p>\n    </div>\n\n    <!-- Q31 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.3); border-radius: 12px; padding: 18px; margin-bottom: 18px;\">\n      <h3 style=\"color: #00E5FF; font-size: 16px; font-weight: 700; margin: 0 0 10px 0;\">Q31: Discuss the universal symbolism of \"twelve\", \"arms\", and \"shade\" as deployed by Pablo Neruda.</h3>\n      <p style=\"margin: 0 0 8px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span></p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E5FF;\">1. The Cosmic Dimension of 'Twelve':</b> Neruda opens and closes the poem with the ritual counting to twelve. Twelve is a universally recognized cosmic marker: the twelve hours of the clock, the twelve months of the year, and the twelve signs of the zodiac. It represents temporal wholeness and cosmic order, establishing an egalitarian interval where every person across every time zone can participate simultaneously.</p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E5FF;\">2. The Double Meaning of 'Arms':</b> The line <i>\"not move our arms so much\"</i> operates as a masterful pun. Anatomically, 'arms' refers to human limbs worn ragged by relentless capitalist production; militarily, 'arms' signifies guns, artillery, and nuclear arsenals. By holding their arms still, humans practice non-violence both toward their weary bodies and toward their fellow human beings.</p>\n      <p style=\"margin: 0;\"><b style=\"color: #00E5FF;\">3. The Sanctuary of 'Shade':</b> The image of walking with brothers \"in the shade\" symbolizes shelter from scorching hostility, ideological fanaticism, and destructive competition. It offers a pastoral sanctuary where reconciliation flourishes away from the harsh glare of battlefield politics.</p>\n    </div>\n\n    <!-- Q32 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.3); border-radius: 12px; padding: 18px; margin-bottom: 18px;\">\n      <h3 style=\"color: #00E5FF; font-size: 16px; font-weight: 700; margin: 0 0 10px 0;\">Q32: Examine the existential predicament of modern man as portrayed in \"Keeping Quiet\". What remedy does Neruda propose?</h3>\n      <p style=\"margin: 0 0 8px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span></p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E5FF;\">1. The Existential Diagnosis:</b> Neruda identifies two interrelated psychological maladies plaguing contemporary civilization: relentless \"single-mindedness\" regarding commercial movement, and a deep-seated \"sadness\" resulting from a complete lack of self-comprehension. Modern man is trapped in a ceaseless existential race, terrified by his mortality (\"threatening ourselves with death\") and substituting frenetic activity for inner meaning.</p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E5FF;\">2. The Therapeutic Remedy:</b> The remedy proposed is a \"huge silence\"—a collective meditative pause that punctures our perpetual dread. By disconnecting from the din of machines and linguistic bickering, humanity creates space for authentic self-examination. In this hiatus, self-awareness replaces fear, and mutual empathy overcomes tribal hostility.</p>\n      <p style=\"margin: 0;\"><b style=\"color: #00E5FF;\">3. Critical Conclusion:</b> Neruda's prescription is profoundly psychological: by confronting the silence we so desperately evade, we heal the chronic existential loneliness that drives us to war, environmental plunder, and self-destruction.</p>\n    </div>\n\n    <!-- Q33 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.3); border-radius: 12px; padding: 18px; margin-bottom: 18px;\">\n      <h3 style=\"color: #00E5FF; font-size: 16px; font-weight: 700; margin: 0 0 10px 0;\">Q33: How does Neruda employ visual, auditory, and tactile imagery to create an atmosphere of transformative stillness?</h3>\n      <p style=\"margin: 0 0 8px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span></p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E5FF;\">1. Auditory & Acoustic Restraint:</b> The auditory imagery is paradoxically defined by the cessation of sound: engines falling silent, voices dropping into quietude, and the eerie absence of battlefield detonations. The silence transforms into a physical presence, generating an atmosphere of \"sudden strangeness\" where acoustic calm reflects spiritual peace.</p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E5FF;\">2. Visual & Tactile Contrast:</b> Visually, the poem juxtaposes toxic plumes of \"wars with gas\" and smoke of \"wars with fire\" against the crisp, serene picture of soldiers putting on \"clean clothes\" and resting \"in the shade\". Tactile imagery is intensely felt in the salt gatherer's raw \"hurt hands\" and the chilling expanse of the \"cold sea\".</p>\n      <p style=\"margin: 0;\"><b style=\"color: #00E5FF;\">3. Critical Conclusion:</b> Through these vivid sensory contrasts, Neruda renders the transition from chaotic, brutal strife to serene fraternity emotionally palpable, compelling the reader to yearn for the regenerative beauty of quietness.</p>\n    </div>\n\n    <!-- Q34 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.3); border-radius: 12px; padding: 18px; margin-bottom: 22px;\">\n      <h3 style=\"color: #00E5FF; font-size: 16px; font-weight: 700; margin: 0 0 10px 0;\">Q34: Evaluate the structural arc of \"Keeping Quiet\" from its opening imperative to its closing departure.</h3>\n      <p style=\"margin: 0 0 8px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span></p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E5FF;\">1. Opening & Collective Ingathering:</b> The poem follows a symmetrical, circular arc. It begins with an inclusive, gentle invitation: <i>\"Now we will count to twelve / and we will all keep still.\"</i> The poet acts as a spiritual guide, gathering disparate humans across linguistic, political, and cultural divides into a unified circle of contemplation.</p>\n      <p style=\"margin: 0 0 8px 0;\"><b style=\"color: #00E5FF;\">2. Thematic Deepening & Resolution:</b> In the middle stanzas, Neruda progressively broadens the scope—from personal labor (salt gatherer) to ecological care (whales) to international geopolitics (green wars). He tackles the philosophical objection of inactivity vs death, resolving it through the organic metaphor of the living Earth.</p>\n      <p style=\"margin: 0;\"><b style=\"color: #00E5FF;\">3. Graceful Departure & Empowerment:</b> The poem culminates in the mirror line: <i>\"Now I'll count up to twelve / and you keep quiet and I will go.\"</i> The guide steps back into silence, passing moral agency to humanity. The reader is left alone in quietness to experience personal rebirth and carry forward the torch of universal peace.</p>\n    </div>\n  </div>\n\n  <!-- SECTION D: NCERT TEXTBOOK EXERCISES -->\n  <div style=\"margin-bottom: 20px;\">\n    <div style=\"background: linear-gradient(135deg, rgba(0, 229, 255, 0.25), rgba(15, 23, 42, 0.95)); border: 1.5px solid #00E5FF; border-radius: 12px; padding: 14px 18px; margin-bottom: 20px;\">\n      <h2 style=\"color: #FFFFFF; font-size: 20px; font-weight: 800; margin: 0 0 4px 0;\">SECTION D: NCERT Textbook Exercises (Thinking About The Poem)</h2>\n      <p style=\"color: #00E5FF; font-size: 13px; font-weight: 600; margin: 0;\">Official Curriculum Solutions • Questions Q35 to Q38</p>\n    </div>\n\n    <!-- Q35 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q35: What will counting up to twelve and keeping still help us achieve?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> Counting to twelve and keeping still provides a brief respite from the frantic rush and aggressive mechanization of modern life. It halts violent warfare and ecological exploitation, allowing human beings to introspect, heal self-inflicted wounds, and realize their common fraternity under an exotic aura of universal peace.</p>\n    </div>\n\n    <!-- Q36 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q36: Do you think the poet advocates total inactivity and death?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> No, the poet explicitly rejects total inactivity and death, stating: <i>\"Life is what it is about; / I want no truck with death.\"</i> He advocates a momentary, mindful pause to reflect on our actions, not permanent cessation. His goal is to enrich and preserve life, purging it of destructive haste and violence.</p>\n    </div>\n\n    <!-- Q37 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q37: What is the 'sadness' that the poet refers to in the poem?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> The 'sadness' refers to the existential anguish arising from man's inability to understand his authentic inner self, compounded by the constant dread of death. Driven by material obsessions and relentless routine, humans inflict suffering on themselves and others, creating a spiritual void.</p>\n    </div>\n\n    <!-- Q38 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 10px; padding: 14px 16px; margin-bottom: 14px;\">\n      <h3 style=\"color: #00E5FF; font-size: 15px; font-weight: 700; margin: 0 0 8px 0;\">Q38: What symbol from Nature does the poet invoke that there can be life under apparent stillness?</h3>\n      <p style=\"margin: 0 0 6px 0;\"><span style=\"color: #00E5FF; font-weight: bold;\">✓ Answer:</span> The poet invokes the symbol of the <b style=\"color: #00E5FF;\">Earth</b>. In winter, the Earth appears dormant, barren, and completely lifeless, yet subterranean processes are quietly nurturing seeds. When the season turns, vibrant life bursts forth, demonstrating that stillness nurtures regeneration rather than death.</p>\n    </div>\n  </div>\n\n</div>\n";

